// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {TimelockController} from "../src/TimelockController.sol";

contract InvMutTest is Test {
    TimelockController c;
    function setUp() public { c = new TimelockController(0, new address[](0), new address[](0)); }
    function testFuzz_property(bytes32 role, address account) public {
        bool hasRoleResult = c.hasRole(role, account);
        if (hasRoleResult) {
            assertTrue(
                c.getRoleAdmin(role) != bytes32(0) || role == 0x00,
                "hasRole returned true for an account that was never granted the role"
            );
        }
    }
}
